// Route contract for this endpoint (read by wf.gateway.auth).
const route = {"method": "POST", "template": "/v1/admin/eval/prompt-runs", "require_user": true, "idempotent": true, "required_consents": [], "roles": ["admin"]};
const item = $input.first();
return [{ json: { ...item.json, t0: Date.now(), route }, binary: item.binary }];

// wf.api.admin_eval_prompt_runs_create > "Validate body"
// POST /v1/admin/eval/prompt-runs  (role admin)
// Body: {prompt (P1_router | P2_profile_extractor | P3_listing_extractor), versions: [int] (required), models: [string]
//        (default: llm.default_model), dataset (default: the prompt's golden set),
//        dataset_version (default 1), item_ids: [string] or limit (a subset, for smoke tests),
//        git_sha, label}
const gw = $input.first().json;
const b = gw.ctx.body;
const details = [];
const PROMPTS = { P1_router: 'p1_router', P2_profile_extractor: 'p2_profile', P3_listing_extractor: 'p3_listing' };
const allowed = ['prompt', 'versions', 'models', 'dataset', 'dataset_version', 'item_ids', 'limit', 'git_sha', 'label'];
for (const key of Object.keys(b)) if (!allowed.includes(key)) details.push({ field: key, issue: 'unknown_field' });
if (!Object.prototype.hasOwnProperty.call(PROMPTS, b.prompt)) details.push({ field: 'prompt', issue: 'unknown' });
if (!Array.isArray(b.versions) || b.versions.length < 1 || b.versions.length > 5 || !b.versions.every((v) => Number.isInteger(v) && v > 0)) {
  details.push({ field: 'versions', issue: 'must_be_array_of_1_to_5_positive_integers' });
}
if (b.models !== undefined && (!Array.isArray(b.models) || b.models.length < 1 || b.models.length > 5 ||
    !b.models.every((m) => typeof m === 'string' && /^[a-z0-9][a-z0-9._:-]{1,79}$/i.test(m)))) {
  details.push({ field: 'models', issue: 'must_be_array_of_1_to_5_model_names' });
}
if (b.dataset !== undefined && (typeof b.dataset !== 'string' || !/^[a-z0-9_]{3,60}$/.test(b.dataset))) details.push({ field: 'dataset', issue: 'invalid_format' });
const dv = b.dataset_version === undefined ? 1 : b.dataset_version;
if (!Number.isInteger(dv) || dv < 1) details.push({ field: 'dataset_version', issue: 'must_be_positive_integer' });
if (b.item_ids !== undefined && (!Array.isArray(b.item_ids) || b.item_ids.length > 500 || !b.item_ids.every((x) => typeof x === 'string' && /^[a-z0-9-]{1,40}$/.test(x)))) {
  details.push({ field: 'item_ids', issue: 'must_be_array_of_ids' });
}
if (b.limit !== undefined && (!Number.isInteger(b.limit) || b.limit < 1 || b.limit > 1000)) details.push({ field: 'limit', issue: 'must_be_integer_1_1000' });
for (const f of ['git_sha', 'label']) {
  if (b[f] !== undefined && (typeof b[f] !== 'string' || b[f].length > 80 || !/^[\w.:/ -]*$/.test(b[f]))) details.push({ field: f, issue: 'invalid_format' });
}
if (details.length) {
  return [{ json: { ok: false, status: 422, gw, error: { code: 'VALIDATION_FAILED', message: 'Request body is invalid', details } } }];
}
const input = { prompt: b.prompt, versions: [...new Set(b.versions)], models: b.models ? [...new Set(b.models)] : null,
  dataset: b.dataset || PROMPTS[b.prompt], dataset_version: dv, item_ids: b.item_ids || null, limit: b.limit || null,
  git_sha: b.git_sha || null, label: b.label || null };
const idem = gw.idempotency ? `${gw.idempotency.scope}:${gw.idempotency.key}` : null;
return [{ json: { ok: true, gw, params: [JSON.stringify(input), gw.ctx.user_id, idem, 'eval_prompts'] } }];

// Admin job endpoints > "Accepted"
// Input: the app.jobs row created for this request (after the worker was started).
// 202 with the job id and where to poll (spec 6.1 asynchronous calls).
const gw = $('Validate body').first().json.gw;
const row = $('Create job').first().json;
if (!row || !row.id) {
  return [{ json: { ok: false, gw, status: 422, error: { code: 'VALIDATION_FAILED', message: 'Request body is invalid', details: [{ field: row && row.reason || 'jurisdiction', issue: 'unknown' }] } } }];
}
return [{ json: { ok: true, gw, status: 202, data: { job_id: row.id, type: row.type, status: row.status, status_url: `/v1/jobs/${row.id}` } } }];

// Admin job endpoints > "Database error"
// Error output of a database step: the client gets 503, the log gets the redacted text.
// Text of the error carried by an item on a node's error output.
// n8n puts either a string or an object {message, description, ...} in json.error.
function errorText(json) {
  const e = json && (json.error !== undefined ? json.error : json);
  if (e == null) return '';
  if (typeof e === 'string') return e;
  const parts = [e.message, e.description, e.cause && e.cause.message].filter((x) => typeof x === 'string' && x);
  return parts.length ? parts.join(' | ') : JSON.stringify(e);
}
// Postgres error details echo the offending value, e.g. Key (email)=(a@b.c).
// Values are removed before anything is logged.
function redactPg(msg) {
  return String(msg || '').replace(/\)=\([^)]*\)/g, ')=(redacted)');
}
if (typeof module !== 'undefined') module.exports = { errorText, redactPg };

const gw = $('Validate body').first().json.gw;
const msg = errorText($input.first().json);
return [{ json: { ok: false, gw, status: 503, error: { code: 'UPSTREAM_UNAVAILABLE', message: 'A backend dependency is unavailable', details: [] }, log: { reason: 'database_error', detail: redactPg(msg).slice(0, 300) } } }];

// Shared by every API workflow > "Envelope"
// Input: either a handler result {ok:true, status, data, gw} or a rejection
// from the gateway or a handler {ok:false, status, error | replay+response}.
// Output: {status, response, finish} where finish is the app.api_finish payload.
const x = $input.first().json;
const gw = x.gw || x;                       // handlers carry the gateway item in x.gw
const t0 = gw.t0 || Date.now();
const latency = Date.now() - t0;
const requestId = gw.request_id || (gw.ctx && gw.ctx.request_id) || null;
let status, response;
if (x.replay) {
  status = x.status;
  response = x.response;                    // stored response, returned unchanged
} else if (x.ok) {
  status = x.status || 200;
  response = { request_id: requestId, data: x.data ?? {}, meta: { latency_ms: latency, ...(x.meta || {}) } };
} else {
  status = x.status || 500;
  const e = x.error || { code: 'INTERNAL', message: 'Internal error', details: [] };
  response = { request_id: requestId, error: { code: e.code, message: e.message, details: e.details || [] } };
}
const finish = {
  request_id: requestId,
  workflow: $workflow.name,
  n8n_execution_id: String($execution.id),
  user_id: (gw.ctx && gw.ctx.user_id) || '',
  channel: 'api',
  status_code: status,
  latency_ms: latency,
  error_code: response && response.error ? response.error.code : null,
  idempotency: gw.idempotency || null,
  idempotency_replay: !!x.replay,
  response_body: response,
  result_user_id: x.result_user_id || null,
  // agent steps of the request (spec 8.3), written to ai.agent_steps with the execution
  steps: Array.isArray(x.steps) ? x.steps : [],
  // reason and detail go to ai.executions.error only, never to the client
  error_detail: x.log ? [x.log.reason, x.log.detail].filter(Boolean).join(': ').slice(0, 500) : null,
};
const headers = { 'X-Request-Id': requestId || '', 'Cache-Control': 'no-store' };
if (status === 429) {
  const d = (response.error && response.error.details || []).find((y) => y.retry_after_s);
  if (d) headers['Retry-After'] = String(d.retry_after_s);
}
return [{ json: { status, response, finish, headers } }];
